using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "InventiveActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/InventiveActionCustomDescription", order = 0)]
public class InventiveActionCustomDescription : WhereXTimesCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedDiscardDieFromHand(), int.Parse(amountModified));
		DiscardWithActionAction discardWithActionAction = battleAction as DiscardWithActionAction;
		string text2 = discardWithActionAction.BattleAction.GetActionDescription(discardWithActionAction.FixedActionAmount).RemoveLast().LowercaseFirst();
		return text + "\n" + Smart.Format(base.localizationManager.GetLocalizedIfYouDo(), Smart.Format(base.localizationManager.GetLocalizedString("ForEachDieDiscarded"), text2.RemoveLastIfDotOrComma()));
	}
}
